import os
from datetime import datetime, timedelta

memories_dir = "/Users/ktoclaw/.hermes/memories"
cutoff = datetime.now() - timedelta(days=7)
cutoff_str = cutoff.strftime("%Y-%m-%d")

files_to_delete = []
files_to_keep = []

for f in sorted(os.listdir(memories_dir)):
    if f.endswith('.lock'):
        continue
    path = os.path.join(memories_dir, f)
    if not os.path.isfile(path):
        continue
    # extract date from filename patterns like research-2026-06-04.md
    date_part = None
    if f.startswith(('research-', 'war-news-', 'stock-radar-', 'victor-study-')) and f.endswith('.md'):
        date_part = f.split('-')[-1].replace('.md', '')
    elif f in ('MEMORY.md', 'USER.md'):
        files_to_keep.append(f)
        continue

    if date_part:
        try:
            file_date = datetime.strptime(date_part, "%Y-%m-%d")
            if file_date < cutoff:
                files_to_delete.append((f, date_part))
            else:
                files_to_keep.append(f)
        except:
            files_to_keep.append(f)

print(f"Cutoff: {cutoff_str}")
print(f"\nTO DELETE ({len(files_to_delete)} files, older than {cutoff_str}):")
for f, d in files_to_delete:
    print(f"  {f}")

print(f"\nTO KEEP ({len(files_to_keep)} files):")
for f in files_to_keep:
    print(f"  {f}")
"}

