import os
from datetime import datetime, timedelta

cron_output_dir = "/Users/ktoclaw/.hermes/cron/output"
cutoff = datetime.now() - timedelta(days=7)

old_dirs = []
for job_id in os.listdir(cron_output_dir):
    job_path = os.path.join(cron_output_dir, job_id)
    if not os.path.isdir(job_path):
        continue
    for ts_dir in os.listdir(job_path):
        ts_path = os.path.join(job_path, ts_dir)
        if not os.path.isdir(ts_path):
            continue
        mtime = datetime.fromtimestamp(os.path.getmtime(ts_path))
        if mtime < cutoff:
            old_dirs.append(ts_path)

print(f"Old cron output dirs to delete ({len(old_dirs)}):")
for d in sorted(old_dirs):
    print(f"  {d}")
